/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
Module 2.6 — Early Warning, Intervention & Servicing Strategy

Program     : 177_msbf_m2_6_acceptance_finalize_v0_2.sql
Version     : v0.2

Purpose
-------
Finalize M2.6 acceptance after independently verifying positive and negative
controls, physical counts, recommendation-only boundaries, latest/archive
reproduction, canonical identity, matched stress non-improvement and zero
blocking exceptions.

Required result
---------------
acceptance_status = PASS; final_run_status = M2_6_ACCEPTED; gate_status = PASS.
============================================================================ */
BEGIN;
SET LOCAL statement_timeout='45min'; SET LOCAL work_mem='128MB'; SET LOCAL jit=off;
DROP TABLE IF EXISTS _m2_6_acceptance;
CREATE TEMP TABLE _m2_6_acceptance ON COMMIT PRESERVE ROWS AS WITH run_context AS (SELECT run_id,run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1), registry AS (SELECT * FROM msbf_ctl.m2_6_intervention_strategy_contract_registry WHERE module1_run_id=(SELECT run_id FROM run_context)), controls AS (SELECT count(*) FILTER (WHERE evidence_code LIKE 'M2_6_POS_%')::bigint AS positive_checks, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_POS_%' AND status='PASS')::bigint AS positive_passes, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_POS_%' AND status<>'PASS')::bigint AS positive_failures, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_NEG_%')::bigint AS negative_checks, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_NEG_%' AND status='PASS')::bigint AS negative_passes, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_NEG_%' AND status<>'PASS')::bigint AS negative_failures, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_%' AND evidence_code NOT LIKE 'M2_6_POS_%' AND evidence_code NOT LIKE 'M2_6_NEG_%' AND evidence_code<>'M2_6_ACCEPTANCE_SUMMARY')::bigint AS generation_evidence_rows, count(*) FILTER (WHERE evidence_code LIKE 'M2_6_%' AND status='FAIL')::bigint AS failed_evidence_rows FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM run_context)), physical AS (SELECT (SELECT count(*) FROM msbf_m2.advance_intervention_source_snapshot WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS source_rows, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS strategy_rows, (SELECT count(*) FROM msbf_m2.portfolio_intervention_strategy_summary WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS portfolio_rows, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS latest_rows, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_archive WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS archive_rows, (SELECT count(*) FROM msbf_m2.v_m2_6_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS comparison_rows, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM run_context) AND (merchant_contact_executed_flag OR payment_change_executed_flag OR write_off_or_charge_off_executed_flag OR legal_or_collection_action_executed_flag OR external_notice_generated_flag OR production_adverse_action_notice_flag))::bigint AS executed_boundary_rows, (SELECT count(*) FROM msbf_m2.v_m2_6_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM run_context) AND (stress_strategy_improvement_flag OR stress_action_improvement_flag))::bigint AS stress_improvement_rows, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_latest AS latest FULL OUTER JOIN msbf_m2.advance_intervention_strategy_archive AS archive ON archive.module1_run_id=latest.module1_run_id AND archive.contract_version=latest.contract_version AND archive.scenario_id=latest.scenario_id AND archive.merchant_application_id=latest.merchant_application_id WHERE coalesce(latest.module1_run_id,archive.module1_run_id)=(SELECT run_id FROM run_context) AND (latest.contract_row_hash IS DISTINCT FROM archive.contract_row_hash OR archive.contract_payload IS DISTINCT FROM (to_jsonb(latest)-'created_at')))::bigint AS archive_mismatches, (SELECT canonical_entities FROM msbf_m2.v_m2_6_canonical_hash WHERE module1_run_id=(SELECT run_id FROM run_context))::bigint AS physical_canonical_entities, (SELECT combined_set_hash FROM msbf_m2.v_m2_6_canonical_hash WHERE module1_run_id=(SELECT run_id FROM run_context)) AS physical_combined_set_hash, (SELECT count(*) FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM run_context) AND gate_id='M2_6_EARLY_WARNING_INTERVENTION_SERVICING_STRATEGY')::bigint AS existing_gate_rows, (SELECT count(*) FROM msbf_ctl.profile_resolution_error WHERE run_id=(SELECT run_id FROM run_context) AND severity='BLOCKING')::bigint AS blocking_errors) SELECT run_context.run_id, run_context.run_status AS prior_run_status, registry.contract_status AS prior_contract_status, controls.*, physical.*, registry.canonical_entities, registry.combined_set_hash, registry.contract_set_hash, CASE WHEN run_context.run_status='M2_6_VALIDATED' AND registry.contract_status='VALIDATED' AND controls.positive_checks=120 AND controls.positive_passes=120 AND controls.positive_failures=0 AND controls.negative_checks=20 AND controls.negative_passes=20 AND controls.negative_failures=0 AND controls.generation_evidence_rows=24 AND controls.failed_evidence_rows=0 AND physical.source_rows=59 AND physical.strategy_rows=59 AND physical.portfolio_rows=2 AND physical.latest_rows=59 AND physical.archive_rows=59 AND physical.comparison_rows=15 AND physical.executed_boundary_rows=0 AND physical.stress_improvement_rows=0 AND physical.archive_mismatches=0 AND physical.physical_canonical_entities=284 AND registry.canonical_entities=284 AND registry.combined_set_hash IS NOT DISTINCT FROM physical.physical_combined_set_hash AND physical.existing_gate_rows=0 AND physical.blocking_errors=0 THEN 'PASS' ELSE 'FAIL' END AS acceptance_status FROM run_context CROSS JOIN registry CROSS JOIN controls CROSS JOIN physical;
DO $guard$ DECLARE v record; BEGIN SELECT run_id, acceptance_status INTO v FROM _m2_6_acceptance; IF v.acceptance_status<>'PASS' THEN RAISE EXCEPTION 'M2.6 acceptance preconditions failed: %', (SELECT row_to_json(a) FROM _m2_6_acceptance AS a); END IF; PERFORM msbf_ctl.m2_6_assert_acceptance_ready(v.run_id); END; $guard$;
UPDATE msbf_ctl.m2_6_intervention_strategy_contract_registry SET contract_status='ACCEPTED', accepted_at=clock_timestamp() WHERE module1_run_id=(SELECT run_id FROM _m2_6_acceptance);
UPDATE msbf_ctl.run_registry SET run_status='M2_6_ACCEPTED', notes=coalesce(notes,'')||' | M2.6 early warning, intervention and servicing strategy accepted.' WHERE run_id=(SELECT run_id FROM _m2_6_acceptance);
INSERT INTO msbf_ctl.acceptance_gate_result(run_id,gate_id,review_version,result_status,observed_value,threshold_value,finding,residual_limitation,reviewer_role) SELECT run_id, 'M2_6_EARLY_WARNING_INTERVENTION_SERVICING_STRATEGY', 1, 'PASS', combined_set_hash, '120 positive; 20 negative; 59 strategy rows; zero executed servicing actions; zero stress improvements; zero archive mismatches', 'M2.6 recommendation-only intervention and servicing strategy accepted.', 'Recommendation-only synthetic strategy; no executed merchant contact, payment change, workout, write-off, legal action, external notice or production adverse-action notice.', 'Independent Validation / Project Owner' FROM _m2_6_acceptance;
INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation) SELECT run_id,'M2_6_ACCEPTANCE_SUMMARY','PORTFOLIO','M2_6_EARLY_WARNING_INTERVENTION_SERVICING_STRATEGY_ACCEPTANCE',NULL::numeric(28,10),combined_set_hash,'ACCEPTANCE','PASS','Formal M2.6 acceptance: recommendation-only early-warning intervention and servicing strategy accepted.' FROM _m2_6_acceptance;
ALTER TABLE _m2_6_acceptance ADD COLUMN final_run_status text, ADD COLUMN final_contract_status text, ADD COLUMN gate_status text;
UPDATE _m2_6_acceptance AS a SET final_run_status=(SELECT run_status FROM msbf_ctl.run_registry WHERE run_id=a.run_id), final_contract_status=(SELECT contract_status FROM msbf_ctl.m2_6_intervention_strategy_contract_registry WHERE module1_run_id=a.run_id), gate_status=(SELECT result_status FROM msbf_ctl.acceptance_gate_result WHERE run_id=a.run_id AND gate_id='M2_6_EARLY_WARNING_INTERVENTION_SERVICING_STRATEGY' AND review_version=1);
DO $final$ DECLARE v record; BEGIN SELECT final_run_status,final_contract_status,gate_status INTO v FROM _m2_6_acceptance; IF v.final_run_status<>'M2_6_ACCEPTED' OR v.final_contract_status<>'ACCEPTED' OR v.gate_status<>'PASS' THEN RAISE EXCEPTION 'M2.6 final acceptance state failed: %', row_to_json(v); END IF; END; $final$;
COMMIT;
SELECT * FROM _m2_6_acceptance;
